INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1457509-mgt449', 'stk-practice', 'MGT 449', 'info', '{"desc": "المادة تغير اسمها لـ Strategic management\n\nاتوقع محد قييمها لان اللي ياخذوها غالبا اخر ترم وبيتخرجو\n\nالمادة شبيهة بـMgt301 وتتكرر اشياء كثير\n\nاخذتها مع ازهر وما انصح فيه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-449-business-policy/120993/2", "user": "Practice", "ts": 1473716613000, "tid": 120993, "pn": 2}}', 1473716613000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-phenomenon-mgt449', 'stk-phenomenon', 'MGT 449', 'doc', '{"docs": [{"id": "stk-dr-f98458", "n": "Dr. Abdulwahab S. Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ردود سابق من بعض الاخوان :\n\nوإذا أردت الإستمتاع بالمادة خذها مع القحطاني ولكن حضر الدرس واحضر على التوقيت وشارك واسأل وسلم واجبات ومشاريع في الوقت المحدد وان طلب برزنتيشن كن أول واحد وكثر من الزيارات المكتبية وحاول أن تنشيء علاقة معه مبنية على الرغبة في تعلم الإبداع الإداري وحاول أن تنهل من خبرته الواسعة\n\nأسئلته متوسطة وصعبة ولازم تذاكر المادة من جد\n\nولكن ان حققت الشروط اللي فوق وجبت سي حيعطيك بي أو أكثر ولا يعطي إلا للمهتم اللي يحاول أن يتعلم ويناقش ويبادر ويلتزم\n\nفي النهاية لا غياب …لا تأخير… مشاركة ومناقشة واجتهاد وزيارات مكتبية واستشارات تخطيطية مستقبلية…تأخذ أكثر من حقك بكثير\n\nmgt 449 يعطيه كذا واحد اخذته عند دكتور عبد الوهاب القحطاني وانصحك تاخذ معه لكن اهتم بالحضور وتاخذ ان شاء الله اكثر من حقك\n\nوهذي زياده :\n\nhttp://skfupm.kfupm.edu.sa/showthread.php?t=34365\n\nhttp://skfupm.kfupm.edu.sa/showthread.php?t=22305", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p853168-mgt449", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulwahab-s-al-gahtani/98458/8", "user": "Phenomenon", "ts": 1308076284000, "tid": 98458, "pn": 8}}]}', 1308076284000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5136-mgt449', 'stk-user5136', 'MGT 449', 'doc', '{"docs": [{"id": "stk-dr-f98459", "n": "Dr. Mourad Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "توي امس خلصت الفاينال للمادة mgt449\n\nالصوت والشرح واضح\nمافي كوزات ولا هوم وركات … بس في قروب بروجكت+ 2 كيس ستدي + قروب برزنتيشن للبروجكت\nكلهم في اخر السمستر\n\nالشهادة لله الدكتور طول السمستر ماقصر معنا\nيحاول يسهل المادة على الطلاب باللي يقدر عليه\nالمحاظرة ما تقعد فيها اكثر من 40 دقيقة … يعطيك المهم وخلاص\nالتحضير احيانا اول المحاضرة واحيانا اخر المحاضرة\nولا يحاسب على التأخير\n\nالمياجر … TB\n\nللأسف الطلاب اخذو راحتهم مع الدكتور الى ان عصب علينا\nوفاجأنا بفاينال essay دمرنا فيه 😲", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1223648-mgt449", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mourad-mansour/98459/8", "user": "user5136", "ts": 1368833406000, "tid": 98459, "pn": 8}}]}', 1368833406000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-mgt449', 'stk-guest', 'MGT 449', 'doc', '{"docs": [{"id": "stk-dr-f98459", "n": "Dr. Mourad Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور حبيب وشرحه ممتاز جدا ومتفهم\nأخذت معه MGT 449 في 201 والوضع اونلاين\nوقسمنا لقروبات حق بروجكت بس ماكان في معايير واضحه للتقييم فخسفنا كثيير بس بعدين سوى ابقريد لنا\nالأفرج كان معه أتوقع A بعد الابقريد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527923-mgt449", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mourad-mansour/98459/14", "user": "Guest", "ts": 1610830313000, "tid": 98459, "pn": 14}}]}', 1610830313000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hisham.s-mgt449', 'stk-hisham.s', 'MGT 449', 'doc', '{"docs": [{"id": "stk-dr-f98466", "n": "Dr. Azhar Kazmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا معاه هالسمستر 152- كورس mgt449 :\nبنود التقييم :\n\nالتحضير : يومياً\nطريقة الشرح : سلايدات ونقاش.\nالكويزات : لايوجد\nالمياجر: 2 مياجر-كل ميجرعباره عن 45 MCQs من إعداد الدكتور .\nالفاينلات : 60 MCQs + خمسة أسئلة مقالية تختار منها 3 (short esays qustions)\nالفاينل كان متوسط (الاختيارات كمستوى المياجر ) والريتن كان أساسيات بالمادة.\nالقريد النهائي: N\\A\nالصوت: ممتاز\nإضافات :\nالدكتور متمكن في مجاله ولديه فهم عميق للمادة ماشاء الله وهادي ومستمع جيّد للطلاب ونقاشاتهم.\nمن بداية الفصل الدراسي السيلابوس يحتوي ويفصل لك كل شيء .\n\nالأعمال الفصلية والإختبارات وتوزيع الدرجات كالتالي :\n\nMajor examination I : 15%\nMajor examination II : 15%\nCase presentation : 10%\nHome assignment: : 10%\nProject paper report : 10%\nProject paper presentation : 10%\nFinal examination : 30%\nحتى الآن لم ترصد الدرجات والله يوفق الجميع يارب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1447396-mgt449", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-azhar-kazmi/98466/12", "user": "hisham.s", "ts": 1461514812000, "tid": 98466, "pn": 12}}]}', 1461514812000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-mgt449', 'stk-practice', 'MGT 449', 'doc', '{"docs": [{"id": "stk-dr-f98466", "n": "Dr. Azhar Kazmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT449 - Term 152\n\n1- الدكتور هندي لهجته شبه مفهومه … خطه سيء جدا جدا ولا ينفهم كانه يكتب هندي مو انقليزي !\n2- شرحه ممل ويحب يطول الكلاس حتى لو كان مجرد برزنتيشن والشباب خلصو بدري يقوم يشرح البرزنتيشن حقهم عشان ما يطلعنا قبل الوقت ويقعد يطالع بساعته ، انك تشرح البرزنتيشن هذا احتقار للطلاب اللي قدمو اصلا !! واذا سويت برزنتيشنك وخلصت يقعد ساعة يهرج معاك ويشرح لك الا بيطلع نفسه فاهم ياخي ندري انك فاهم والله\n3- تراه حقود ، انتبه تطلع جوالك لانه فعلا يحقد ويغير معاملته معاك بدون ما يحسسك\n4- المادة ستاندرد ـ ميجر ون وميجر تو الافرج 10 من 15 والهايست 12 ، 45 اختيار تقيس فهمك العميق وليس حفظك\n5- اول الترم كان حبيب حس اننا طفشنا من شرحه والشباب زودوها يتاخرون ساعة كاملة عن الكلاس قلب وصار يعصب في ذي النقطة ما الومه لان فيه ناس ما تنعطى وجه\n6- تقييمه للبرزنتيشن دقيق جدا يعطيك درجتك بالانصاص عادي عنده\n7- تقييمه للهومورك ادق من البرزنتيشن ، اول مرة اشوف هومورك صفحتين يبغى فيه رفرنس ! ولا يوضحلك ايش المطلوب منك يتوقع انك طالب ماستر بحكم انه ذا الترم رجع يدرس بكالريوس بعد سنوات كثيرة كان يدرس ماستر\n8- المادة جدا سهلة واغلب كلامها في mgt301 لكن مع الحبيب ذا بتصير تدور ال c+ بمادة قريد\n9- يعني شايف انه ميجرك اختيارات والافرج طايح بالنسبة لمادة سهلة تقوم تخلي الفاينل اختيارات + ريتن !! ما تدري كيف يفكر رغم ان كل الكلاس حرفيا اعترض لكنه مصر يقول احسن لكم، غير كذا جايبلنا ميجر من ترم 92 ما فيه حيل يغير الرقم حتى وما تدري الكتاب نفسه ولا تغير ولا يقبل نقاشك\n10- مجملا ما انصح فيه لانه ما يرضيه ولا شي حط في بالك تتعب على بروجكت او هومورك تلقاه معطيك نص الدرجة لانه يتوقع شي ابداعي واحترافي من طلاب بكالريوس ، ما ينفع لك اذا ودك تخلص المادة ذا يبغاله قعدة وجهد\n11- انا انغريت بالتعليقات اللي فوق بالذات اللي يقول السلايدات تكفي وطلباته سهلة! ، لا يا عزيزي طلباته قلق وما تلقى معلومات عنها ولازم تقرا الكتاب وتفهم ولا ما بتعرف تحل اسئلته\n\nاخيرا ، هذا الكلام يمثل رأيي وتجربتي مع الدكتور ممكن تجربه ويعجبك وممكن العكس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448533-mgt449", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-azhar-kazmi/98466/13", "user": "Practice", "ts": 1462882867000, "tid": 98466, "pn": 13}}]}', 1462882867000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
